/**
 * The one place where the app's HTTP contract lives.
 *
 * Written from docs/api/openapi.json (generated by `python -m backend openapi`).
 * Every shape below names the OpenAPI path and operation it belongs to.
 *
 * KNOWN ISSUE IN THE EXPORTED FILE: FastAPI's default HTTPValidationError /
 * ValidationError 422 models are still present, but the backend replaces every
 * failure body with the uniform ErrorResponse. This file deliberately models
 * only ErrorResponse and does not import or re-declare the framework's default
 * 422 body.
 *
 * A shape is marked ASSUMED where docs/api/openapi.json is silent about the
 * exact field names or values. Those shapes were checked against the backend's
 * serializers; they must be re-checked if the generated OpenAPI document starts
 * describing them.
 */

/** Fixed backend error-code table (OpenAPI types `code` only as a string). */
export type ErrorCode =
  | 'UNAUTHENTICATED'
  | 'FORBIDDEN'
  | 'NOT_FOUND'
  | 'CONFLICT'
  | 'INVALID_REQUEST'
  | 'IDEMPOTENCY_KEY_REUSED'
  | 'RATE_LIMITED'
  | 'INTERNAL_ERROR';

/**
 * `#/components/schemas/ErrorResponse` - the body of every API failure.
 * The default 422 validation model in the exported file is intentionally not
 * modelled; the real 422 body is this shape with code INVALID_REQUEST.
 */
export interface ErrorResponse {
  error: {
    code: string;
    message: string;
    request_id: string;
  };
}

/**
 * `POST /auth/otp` (operation `request_otp_auth_otp_post`) request body,
 * `#/components/schemas/OtpRequestBody`. Unknown fields are rejected by the
 * backend; the app sends only roll_number.
 */
export interface OtpRequest {
  roll_number: string;
}

/**
 * `POST /auth/otp` 202 response.
 *
 * ASSUMED: the OpenAPI response schema is only "an object of strings"; the
 * backend handler returns exactly `{status: "accepted"}`.
 */
export interface OtpResponse {
  status: 'accepted';
}

/**
 * `POST /auth/verify` (operation `verify_otp_auth_verify_post`) request body,
 * `#/components/schemas/VerifyRequestBody`. The app sends exactly six digits.
 */
export interface VerifyRequest {
  roll_number: string;
  code: string;
}

/**
 * `POST /auth/verify` 200 response - the only response that carries the
 * plaintext session token, returned once.
 *
 * ASSUMED: the OpenAPI 200 schema is a generic object; the backend serializer
 * returns token, expires_at and the caller's identity. The app saves the token
 * and reads role/verticals from GET /me, not from this body.
 */
export interface SessionResponse {
  token: string;
  expires_at: string;
  person: SessionPerson;
}

/**
 * `POST /auth/verify` 200 `person` object.
 *
 * ASSUMED: field names come from the backend session serializer; OpenAPI is
 * silent. This is not used for authorization in the app.
 */
export interface SessionPerson {
  id: number;
  role: string;
  vertical_ids: number[];
}

/**
 * `GET /me` (operation `me_me_get`) 200 response.
 *
 * ASSUMED: the OpenAPI 200 schema is a generic object; the backend returns a
 * person record with id, name, role, vertical_ids and optionally phone. The app
 * uses role and vertical_ids only from this response, never from input or
 * locally written data.
 */
export interface MeResponse {
  person: Person;
}

/**
 * `GET /me` 200 `person` object.
 *
 * ASSUMED: field names come from the backend visibility serializer; OpenAPI is
 * silent. `phone` is optional because hierarchy visibility may omit it.
 */
export interface Person {
  id: number;
  name: string;
  role: string;
  vertical_ids: number[];
  phone?: string;
}

/**
 * `GET /healthz` (operation `healthz_healthz_get`) 200 response.
 *
 * ASSUMED: the OpenAPI schema is an object of strings; the handler returns
 * exactly `{status: "ok"}`.
 */
export interface HealthResponse {
  status: string;
}

/** Status codes used by the five endpoints in this session. */
export const STATUS = {
  otpAccepted: 202,
  verifyOk: 200,
  logoutOk: 204,
  meOk: 200,
  healthOk: 200,
} as const;

/**
 * Endpoint descriptors. Path and method are copied from docs/api/openapi.json;
 * `operation` is the exported operationId.
 */
export const ENDPOINTS = {
  requestOtp: {
    method: 'POST',
    path: '/auth/otp',
    operation: 'request_otp_auth_otp_post',
  },
  verifyOtp: {
    method: 'POST',
    path: '/auth/verify',
    operation: 'verify_otp_auth_verify_post',
  },
  logout: {
    method: 'POST',
    path: '/auth/logout',
    operation: 'logout_auth_logout_post',
  },
  me: {
    method: 'GET',
    path: '/me',
    operation: 'me_me_get',
  },
  healthz: {
    method: 'GET',
    path: '/healthz',
    operation: 'healthz_healthz_get',
  },
} as const;

export type Endpoint = (typeof ENDPOINTS)[keyof typeof ENDPOINTS];

/** Optional header on mutating routes; 16-64 chars from A-Z a-z 0-9 . _ : - */
export const IDEMPOTENCY_HEADER = 'Idempotency-Key';
